#include <stdio.h>
#include <stdlib.h>

#define MAXN 100005

int head[MAXN], to[2 * MAXN], nxt[2 * MAXN];
int edge_cnt = 0;

void add_edge(int u, int v) {
    to[edge_cnt] = v;
    nxt[edge_cnt] = head[u];
    head[u] = edge_cnt++;
}

int queue[MAXN];
int parent[MAXN];
int order[MAXN];
int sz[MAXN];

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    for (int i = 1; i <= n; i++) {
        head[i] = -1;
    }

    for (int i = 0; i < n - 1; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        add_edge(u, v);
        add_edge(v, u);
    }

    // BFS para determinar a ordem topológica e os pais
    int front = 0, back = 0;
    queue[back++] = 1;
    parent[1] = 0;

    int order_cnt = 0;
    while (front < back) {
        int u = queue[front++];
        order[order_cnt++] = u;

        for (int e = head[u]; e != -1; e = nxt[e]) {
            int v = to[e];
            if (v != parent[u]) {
                parent[v] = u;
                queue[back++] = v;
            }
        }
    }

    // Inicializa o tamanho das subárvores com 1
    for (int i = 1; i <= n; i++) {
        sz[i] = 1;
    }

    // Calcula os tamanhos das subárvores em ordem reversa da BFS
    int min_diff = n;
    for (int i = n - 1; i >= 0; i--) {
        int u = order[i];
        if (parent[u] != 0) {
            sz[parent[u]] += sz[u];
            int diff = n - 2 * sz[u];
            if (diff < 0) diff = -diff;
            if (diff < min_diff) {
                min_diff = diff;
            }
        }
    }

    printf("%d\n", min_diff);

    return 0;
}
